I looked at #16895. It also fixes the resource leak, but it is not enough to fix the use case detailed below
So, adding a closeFile() before the CV_Error() tests in the current #16823 is still better for comfort

```
FILE* fp = fopen(filename.c_str(), "wb");//create empty file
fclose(fp);

{//open a block
    cv::FileStorage fs;
   try{
       fs.open(filename, cv::FileStorage::FORMAT_YAML | cv::FileStorage::READ);
   }
   catch(std::exception& e){
       std::cout << "exception " << e.what() << std::endl;
    }
    int ul = unlink(filename.c_str());//won't unlink since the FileStorage is not yet destroyed
    if (ul != 0)
       std::cout << "cannot unlink" << std::endl;
}//close the block to destroy fs

int ul = unlink(filename.c_str());//will now work since FileStorage is destroyed
if (ul != 0)
    std::cout << "cannot unlink" << std::endl;
```
